<?php
require_once __DIR__.'/../../includes/db.php';require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../includes/business_helpers.php';require_login();$id=(int)($_GET['id']??0);
$st=$conn->prepare('SELECT s.*,c.car_name,c.plate_number,c.chassis_number,c.make,c.model,c.model_year,d.name dalali_name FROM car_sales s JOIN cars c ON c.id=s.car_id LEFT JOIN dalalis d ON d.id=s.dalali_id WHERE s.id=?');$st->bind_param('i',$id);$st->execute();$s=$st->get_result()->fetch_assoc();if(!$s){set_flash('error','Sale not found.');redirect_to('backend/sales/index.php');}$st=$conn->prepare('SELECT p.*,u.name receiver FROM sale_payments p LEFT JOIN users u ON u.id=p.received_by WHERE p.sale_id=? ORDER BY p.payment_date,p.id');$st->bind_param('i',$id);$st->execute();$payments=$st->get_result();$paid=0;$plist=[];while($p=$payments->fetch_assoc()){$paid+=(float)$p['amount'];$plist[]=$p;}$balance=max(0,(float)$s['sale_price']-$paid);$company=car_sales_company_settings($conn);
$page_title='Sale Receipt';include __DIR__.'/../includes/header.php';include __DIR__.'/../includes/leftsidebar.php';?>
<div class="content-page"><div class="report-title no-print"><h1 class="page-title">Sale Receipt / Statement</h1><div><button class="btn" onclick="window.print()">Print</button><a class="btn" href="agreement.php?id=<?=$id?>">Sale Agreement</a><a class="btn btn-dark" href="index.php">Back</a></div></div><div class="card print-sheet">
<div style="text-align:center;margin-bottom:18px"><?php if(!empty($company['logo_path'])):?><img src="<?=e(app_url($company['logo_path']))?>" style="max-height:70px;max-width:220px;object-fit:contain" alt="Logo"><?php endif;?><h1 style="margin:8px 0 2px"><?=e($company['company_name'])?></h1><?php if($company['tagline']):?><div><?=e($company['tagline'])?></div><?php endif;?><div><?=e($company['address']?:'')?><?=e($company['phone']?' | '.$company['phone']:'')?><?=e($company['email']?' | '.$company['email']:'')?></div><?php if($company['tin_number']||$company['registration_number']):?><small>TIN: <?=e($company['tin_number']?:'—')?> &nbsp; Registration: <?=e($company['registration_number']?:'—')?></small><?php endif;?></div>
<hr><h2 style="text-align:center">CAR SALE RECEIPT / STATEMENT</h2><p><strong>Sale #:</strong> <?=str_pad((string)$s['id'],6,'0',STR_PAD_LEFT)?> &nbsp; <strong>Date:</strong> <?=e($s['sale_date'])?></p><h3>Buyer</h3><p><strong>Name:</strong> <?=e($s['buyer_name'])?><br><strong>Phone:</strong> <?=e($s['buyer_phone']?:'—')?><br><strong>Email:</strong> <?=e($s['buyer_email']?:'—')?></p><h3>Vehicle</h3><p><strong>Car:</strong> <?=e($s['car_name'])?><br><strong>Registration:</strong> <?=e(car_sales_plate_label($s['plate_number']))?><br><strong>Chassis:</strong> <?=e($s['chassis_number'])?></p><h3>Financial Summary</h3><table class="table"><tr><th>Sale Price</th><td><?=e($company['currency'])?> <?=money($s['sale_price'])?></td></tr><tr><th>Total Paid</th><td><?=e($company['currency'])?> <?=money($paid)?></td></tr><tr><th>Balance</th><td><?=e($company['currency'])?> <?=money($balance)?></td></tr><tr><th>Status</th><td><?=e($s['payment_status'])?></td></tr></table><h3>Payments</h3><table class="table"><thead><tr><th>Date</th><th>Amount</th><th>Method</th><th>Reference</th><th>Received By</th></tr></thead><tbody><?php foreach($plist as $p):?><tr><td><?=e($p['payment_date'])?></td><td><?=e($company['currency'])?> <?=money($p['amount'])?></td><td><?=e($p['method']?:'—')?></td><td><?=e($p['reference_number']?:'—')?></td><td><?=e($p['receiver']?:'—')?></td></tr><?php endforeach;?></tbody></table><?php if($s['dalali_name']):?><p><strong>Sales referral:</strong> <?=e($s['dalali_name'])?></p><?php endif;?><p><strong>Notes:</strong> <?=e($s['notes']?:'—')?></p><div style="margin-top:50px;display:flex;justify-content:space-between;gap:40px"><div>_________________________<br>Seller / Authorized Staff</div><div>_________________________<br>Buyer Signature</div></div></div></div><?php include __DIR__.'/../includes/footer.php';?>
